def settle(charges, slots):
    total = sum(charges.values())
    allocations = {name: 0 for name in charges}
    if total == 0:
        return allocations
    remainders = {}
    for name, weight in charges.items():
        allocations[name], remainders[name] = divmod(slots * weight, total)
    remaining = slots - sum(allocations.values())
    for name in sorted(charges, key=lambda name: (-remainders[name], name))[:remaining]:
        allocations[name] += 1
    return allocations

charges = {'zebra':7,'gale':5,'fern':5,'iris':0,'alder':5}
original = charges.copy()
result = settle(charges, 7)
assert result == {'zebra':2,'gale':1,'fern':2,'iris':0,'alder':2}
assert charges == original
edge = {'z':1,'a':1}
assert settle(edge, 1) == {'z':0,'a':1}
assert settle({}, 100) == {}
assert settle({'z':0,'a':0}, 100) == {'z':0,'a':0}
assert settle({'b':2**60,'a':2**60}, 2**60+1) == {'b':2**59,'a':2**59+1}
assert settle(dict(reversed(list(charges.items()))), 7) == result
print(result)
print('All checks passed')

